    "sede": "Av. del Consulado Calle 30 #48-152, Campus Piedra de Bolívar, Cartagena 130015, Colombia, Bolívar 3164390360 Ext. 180 pcingenieria@unicartagena.edu.co",
    "valorMatricula": "$8.500.000 por semestre",
