    "sede": "Zaragocilla Carrera 50 #24-63, Campus Zaragocilla, Cartagena 130014, Colombia, Bolívar 3164390360 Ext. 180 mmicrobiologia@unicartagena.edu.co",
    "valorMatricula": "$10.400.000 por año",
    "mallaUrl": "https://drive.google.com/file/d/1XDLY_OAmkyji-tY6eY6nMVxCUwbBVlix/view?usp=sharing",
